styles.css:
& .wp-block-button__link { transition: all var(--wp--custom--motion--duration--100) var(--wp--custom--motion--easing--standard); }
& .wp-block-button__link:hover { background-color: var(--wp--custom--color--action--cta--background-hover); }
& .wp-block-button__link:active { background-color: var(--wp--custom--color--action--cta--background-hover); }
& .wp-block-button__link:focus { outline: 2px solid var(--wp--custom--color--border--focus); outline-offset: 2px; }
& .wp-block-button__link:focus-visible { outline: 2px solid var(--wp--custom--color--border--focus); outline-offset: 2px; }
